CREATE OR REPLACE FUNCTION public.feature_enabled(_key text) RETURNS boolean LANGUAGE sql STABLE SET search_path=public AS $$ SELECT coalesce((SELECT enabled FROM public.feature_settings WHERE key=_key),true) $$;
REVOKE ALL ON FUNCTION public.console_audit() FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.admin_save_question(_id bigint,_stem text,_options jsonb,_answer text,_explanation text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE html text; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Administrator access required'; END IF; IF length(btrim(_stem)) NOT BETWEEN 1 AND 100000 OR length(_explanation)>200000 OR jsonb_typeof(_options)<>'array' OR jsonb_array_length(_options)<2 OR jsonb_array_length(_options)>10 OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(_options) o WHERE o=_answer) THEN RAISE EXCEPTION 'Check question content; the answer must match an option'; END IF; html:=concat(_stem,_explanation,_options::text); IF html ~* '<\s*(script|iframe|object|embed|svg|math|form|style|link|meta|base)' OR html ~* '\son[a-z]+\s*=' OR html ~* '(javascript|vbscript|data)\s*:' THEN RAISE EXCEPTION 'Executable HTML is not allowed'; END IF; UPDATE public.questions SET stem=_stem,options=_options,answer=_answer,explanation=_explanation WHERE id=_id; IF NOT FOUND THEN RAISE EXCEPTION 'Question not found'; END IF; INSERT INTO public.admin_audit(actor_id,action,entity,record_key,changed_fields) VALUES(auth.uid(),'update','questions',_id::text,'["stem","options","answer","explanation"]'); END $$;